  const prompts = [];

  const canonicalize = (text) => String(text ?? '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .trim();

  const isEnvContextBlock = (text) => {
    const t = canonicalize(text);
    return t.startsWith('<environment_context>') && t.includes('</environment_context>');
  };

  const hasUserMessageEvents = state.events.some((e) => e?.obj?.payload?.type === 'user_message');

  let lastCanonical = null;
  const pushPrompt = (text) => {
    const canon = canonicalize(text);
    if (!canon) return;
    if (canon === lastCanonical) return; // adjacent dedupe
    prompts.push(canon);
    lastCanonical = canon;
  };

  for (const e of state.events) {
    const payload = e?.obj?.payload;
    if (!payload || typeof payload !== 'object') continue;
    const payloadType = payload.type;

    if (payloadType === 'user_message' && typeof payload.message === 'string') {
      pushPrompt(payload.message);
      continue;
    }

    if (payloadType === 'message' && payload.role === 'user') {
      const msg = extractMessageText(payload);
